from dental_release.paths import expand as _release_expand
from common import *
import collections, itertools, csv
import matplotlib.pyplot as plt
import matplotlib.tri as mtri

def run():
    (r1, r2, r3, r4) = [read(ROOT / 'rounds' / f'R{i}.json') for i in range(1, 5)]
    r5 = read(ROOT / 'rounds/R5.json') if (ROOT / 'rounds/R5.json').exists() else None
    rows = read(ROOT / 'raw/R2_ROWS.json')
    loads = read(ROOT / 'raw/R3_ROWS.json')
    controls = {k: read(ROOT / 'raw' / f'{k}_CONTROLS.json') for k in ['CONTACT', 'LOAD', 'OUTPUT']}
    by = collections.defaultdict(list)
    for r in rows:
        by[r['track'], r['participant']].append(r)
    table = []
    for ((track, name), rr) in sorted(by.items()):
        scored = [r for r in rr if r['status'] == 'SCORED']
        vals = [r['contact']['symdiff_mm2'] for r in scored if r['contact']['status'] == 'SCORED']
        table.append(dict(track=track, participant=name, requested=len(rr), scored=len(scored), L2_pass=sum((r['L2'] == 'PASS' for r in rr)), median_symdiff_mm2=float(np.median(vals)) if vals else None, robust_pattern_pass=sum((r.get('robust_pattern') == 'PASS' for r in rr))))
    with (ROOT / 'LEADERBOARD.csv').open('w') as f:
        w = csv.DictWriter(f, fieldnames=list(table[0]))
        w.writeheader()
        w.writerows(table)
    toothrows = []
    for r in loads:
        for (t, a) in r.get('classes', {}).items():
            toothrows.append(dict(uid=r['uid'], case_key=r['case_key'], target_fdi=r['source_fdi'], fdi=t, classification=a['classification'], robust_classification=r['robust_classes'][t]['classification'], share_low_pp=a['share_hull_pp'][0], share_high_pp=a['share_hull_pp'][1], zero_attained=a['infimum_attained'], physical='UNKNOWN', resolution='PER_TOOTH'))
    with (ROOT / 'raw/TOOTH_LOAD_SETS.csv').open('w') as f:
        w = csv.DictWriter(f, fieldnames=list(toothrows[0]))
        w.writeheader()
        w.writerows(toothrows)
    pair = controls['OUTPUT']['pairwise_R1_disagreement']
    collision = r4['largest_reported_difference']
    cost = read(ROOT / 'raw/RUN_COST.json') if (ROOT / 'raw/RUN_COST.json').exists() else {'seconds': None, 'peak_child_rss_MiB': None, 'scope': 'full one-command run not yet recorded'}
    total_bytes = sum((p.stat().st_size for p in DATA.rglob('*') if p.is_file()))
    result = dict(schema='gencad-v6-spatial-contact-load-sets-v1', claim_type='capability', review_state='PENDING_INDEPENDENT_REVIEW', status='GEOMETRIC_DISCRIMINATION_DELIVERED_PHYSICAL_LOAD_UNIDENTIFIED', external_referent=REFERENT, additional_external_referents=[r4['external_referent'], read(ROOT / 'PREREG_R3.json')['external_referent']], headline=dict(roof_discriminating_items=r1['discriminating_L2'], roof_requested_items=r1['requested_items'], previous_L1_discriminating_items=0, whole_crown_spatial_discriminating_sites=r2['frontier_discriminating'], whole_crown_load_discriminating_sites=r3['frontier_discriminating'], whole_crown_sites=18, case_clusters=6, whole_crowns_scored=r2['scored'], whole_crowns_requested=r2['requested'], crowns_changing_native_load_classes=r3['crowns_changing_native_classes'], external_same_count_force_difference_pp=collision['force_difference_pp']), rounds={f'R{i}': r for (i, r) in enumerate([r1, r2, r3, r4], 1)}, same_information_control='v4 polygon operator parity and TANDLAST exact axial classifier/KKT actually executed; no algorithm superiority claim', controls=controls, source_norm_admission=r4['source_admission'], sufficiency=[read(ROOT / 'raw/SUFFICIENCY_CONTACT.json'), read(ROOT / 'raw/SUFFICIENCY_LOAD.json')], resolution={'gap': 'PER_POINT', 'contact_patch': 'PER_SURFACE_REGION', 'force_set': 'PER_TOOTH', 'item_counts': 'POPULATION', 'physical_transfer': 'PHENOMENOLOGICAL debt'}, edges=[dict(source='registered antagonist and candidate exterior triangles', target='contact regions and gap-pair intervals', resolution='PER_SURFACE_REGION', timescale='SIMULTANEOUS'), dict(source='labelled gap interval per tooth pair', target='TANDLAST axial contact graph', resolution='PER_SURFACE_REGION', timescale='SIMULTANEOUS'), dict(source='per-tooth load sets', target='candidate design assessment', resolution='PER_TOOTH', timescale='SIMULTANEOUS'), dict(source='published same-tooth repeated counts and force signals', target='count-to-load sufficiency test', resolution='PER_TOOTH', timescale='SIMULTANEOUS', qualification='same session, registration techniques sequential')], limitations=['No loaded contact/force observation matched to these generated crowns', 'Projected contact and unsigned neighbour proximity are geometry, not pressure', 'Unknown FDI accuracy, scan registration error, support, preload, friction and rotation', 'Force hull widths approximately 98 percentage points; high marginal coverage is not accuracy', 'R2 set inclusion is rigorous in real PL arithmetic, but floating rounding and source geometry enclosures missing', 'Only one site has .25 to .125mm refinement check', 'Six repeated case clusters, not 243 independent cases; roof and crown denominators are different', 'Published pooled/contact norms are not individual clinical acceptance limits'], cost=cost, data_artifacts=dict(root=str(DATA), bytes=total_bytes, limit_bytes=3 * 1024 ** 3, files={str(p): sha(p) for p in sorted(DATA.glob('contact_fields/*.npz'))}), phenomenological_debts=[dict(quantity='physical tooth support/compliance', replacement_measurement='same tooth axial force-displacement with declared rate and preload'), dict(quantity='loaded pose/contact map', replacement_measurement='registered loaded scan plus calibrated silicone/pressure map in same specimen'), dict(quantity='count/area to force', replacement_measurement='same-session spatial pressure response, not pooled population mean')])
    oldrows = read(ROOT / 'raw/R1_ROWS.json')
    oldby = collections.defaultdict(list)
    for r in oldrows:
        oldby[r['task_id']].append(r)
    snapshot_nonempty = sum((len({r['L2'] == 'PASS' for r in rr}) > 1 and any((r.get('contact', {}).get('reference', {}).get('area_mm2', 0) > 1e-12 for r in rr)) for rr in oldby.values()))
    result['snapshot_stratification'] = dict(roof_discriminating_with_positive_reference_contact=snapshot_nonempty, roof_discriminating_with_empty_reference_contact=r1['discriminating_L2'] - snapshot_nonempty, complete_crown_positive_contact_passes=sum((r['L2'] == 'PASS' and r['contact']['reference']['area_mm2'] > 1e-12 for r in rows if r['status'] == 'SCORED')), note='Both complete-crown discriminating spatial sites have empty native nominal contact band; discrimination there detects spurious contact.')
    if r5:
        result['rounds']['R5'] = r5
        if (ROOT / 'raw/SUFFICIENCY_TRAJECTORY.json').exists():
            result['sufficiency'].append(read(ROOT / 'raw/SUFFICIENCY_TRAJECTORY.json'))
    dump(ROOT / 'results.json', result)
    (fig, ax) = plt.subplots(2, 3, figsize=(15, 9), constrained_layout=True)
    methods = ['constraint_optimizer', 'field_generator', 'x42_shape', 'x42_contact_branch']
    short = ['LP', 'Field', 'X42 shape', 'X42 contact']
    ax[0, 0].bar(short, [r1['participants'][m].get('PASS', 0) for m in methods], color=['#315b85', '#388c86', '#c29038', '#9669a1'])
    ax[0, 0].set_ylabel('L2 passing items / 1728 requested')
    ax[0, 0].set_title(f"Spatial items: {r1['discriminating_L2']}/1728 discriminate\nL1: 0/1728; descriptive shared panel")
    key = '89d83f17897eb151_molar_crown'
    for (axis, name) in zip([ax[0, 1], ax[0, 2]], ['field_generator', 'x42_shape']):
        r = next((r for r in rows if r['key'] == key and r['participant'] == name and (r['track'] == 'V5B_R3')))
        z = npz(r['field_path'])
        xy = z['xy']
        ff = z['faces']
        pg = z['pred_gap']
        rg = z['reference_gap']
        valid = np.isfinite(pg[ff]).all(1) & np.isfinite(rg[ff]).all(1)
        tr = mtri.Triangulation(xy[:, 0], xy[:, 1], ff)
        tr.set_mask(~valid)
        axis.tripcolor(tr, facecolors=np.ones(len(ff)), vmin=0, vmax=7, cmap='Greys', shading='flat')
        axis.tricontourf(tr, np.nan_to_num(pg, nan=10), levels=[0, 0.1], colors=['#388c8688'])
        axis.tricontour(tr, np.nan_to_num(rg, nan=10), levels=[0, 0.1], colors=['#c14e39'], linewidths=1)
        axis.set_aspect('equal')
        axis.set_xlabel('local x (mm)')
        axis.set_ylabel('local y (mm)')
        axis.set_title(name + ' / ' + r['L2'] + '\nNative band empty; green = spurious contact')
    loadkey = next((r['key'] for r in r3['frontier_items'] if r['discriminates']))
    rr = [r for r in loads if r['key'] == loadkey and r['track'] == 'V5B_R3' and (r['participant'] in methods)]
    codes = {'NEVER': 0, 'CAN': 1, 'MUST': 2}
    ticks = [str(q * 10 + i) for q in range(1, 5) for i in range(1, 9)]
    mat = np.array([[codes[r['classes'][t]['classification']] for t in ticks] for r in rr])
    im = ax[1, 0].imshow(mat, vmin=0, vmax=2, cmap='viridis', aspect='auto')
    ax[1, 0].set_xticks(range(0, 32, 2), ticks[::2], rotation=90)
    ax[1, 0].set_yticks(range(len(rr)), [r['participant'] for r in rr], fontsize=8)
    ax[1, 0].set_title('Conditional axial tooth-load classes\n0 never / 1 can / 2 must')
    ax[1, 0].set_xlabel('FDI; same site, different generated crowns')
    ax[1, 1].bar(['Observation A', 'Observation B'], [collision['A']['force_pp'], collision['B']['force_pp']], color=['#315b85', '#c29038'])
    ax[1, 1].set_ylabel('Reported T-Scan relative force (%)')
    ax[1, 1].set_title(f"External Table 1, tooth {collision['tooth']}\nSame {collision['count']} foil contacts; difference {collision['force_difference_pp']:.1f} pp")
    ax[1, 2].axis('off')
    ax[1, 2].text(0, 1, f"Complete crowns: {r2['scored']}/{r2['requested']} scored\nSpatial discrimination: {r2['frontier_discriminating']}/18 sites\nLoad-set discrimination: {r3['frontier_discriminating']}/18 sites\n\nForce share hulls remain about 0–100%.\nNo matched pressure measurement.\nCounts, area and centroid are insufficient.\n\nResolution: point → patch → tooth.\nStatus: pending independent review.", va='top', fontsize=12)
    fig.suptitle('GenCAD v6: contact pattern distinguishes proposals; physical load remains unidentified', fontsize=15)
    fig.savefig(ROOT / 'figures/demo.png', dpi=150)
    fig.savefig(ROOT / 'figures/demo.pdf')
    plt.close(fig)
    txt = f"# GenCAD v6 — contact pattern and tooth-load sets\n\nThe same four frontier participants now differ on **{r1['discriminating_L2']}/{r1['requested_items']} roof tasks**, compared with **0/1728** at feasibility level. Actual complete crowns differ on **{r2['frontier_discriminating']}/18 sites** for spatial contact and **{r3['frontier_discriminating']}/18 sites** for conditional tooth-load classes. The referent is the original registered [Bite2Text](https://ditto.ing.unimore.it/bite2text/) / [Bits2Bites](https://ditto.ing.unimore.it/bits2bites/) geometry. This answers a geometric reconstruction question, not clinical adequacy or measured pressure. Claim type: capability. PENDING_INDEPENDENT_REVIEW.\n\n| Question | Result | Resolution |\n|---|---:|---|\n| Same-panel roof discrimination | {r1['discriminating_L2']}/1728 | PER_TOOTH decisions, POPULATION count |\n| All four roof maps supported | {r1['all_four_scored']}/1728 | PER_TOOTH |\n| Complete crown proposals scored | {r2['scored']}/{r2['requested']} | PER_TOOTH |\n| Complete crown spatial discrimination | {r2['frontier_discriminating']}/18 sites | PER_TOOTH |\n| Complete crown load-set discrimination | {r3['frontier_discriminating']}/18 sites | PER_TOOTH |\n| Changed native tooth-load classes | {r3['crowns_changing_native_classes']}/234 crowns | PER_TOOTH |\n| Nominal complete crown spatial PASS | {r2['L2_counts'].get('PASS', 0)}/243 | PER_TOOTH |\n| Pattern set bound at ±0.05 mm | {r2['robust_pattern_counts'].get('PASS', 0)} PASS, {r2['robust_pattern_counts'].get('UNKNOWN', 0)} UNKNOWN | PER_SURFACE_REGION |\n| Matched generated-crown pressure observations | 0 | PER_TOOTH |\n\nThe 18 sites belong to six case clusters (four Bite2Text, two Bits2Bites). The 243 requests comprise 189 V5B adapted proposals and 54 missing-form PROOF_LANE_FULL_CROWN proposals; 234 are scored. Preoperative-scan-informed FULL_CROWN rounds are excluded from this information-matched track. All failed requests remain in denominators. Roof tasks cover nine families and are not complete restorations. Level 2 thresholds (1 mm² symmetric difference, at most one component difference, 0.5 mm centroid difference, 0.1 mm² negative-gap area) are frozen engineering queries, not published clinical norms.\n\nThe changed operation retains each contact region's area and coordinates, then replaces the crown's incident edges in the full registered arch before calling TANDLAST. {r3['class_counts']['MUST']} MUST, {r3['class_counts']['CAN']} CAN and {r3['class_counts']['NEVER']} NEVER entries are conditional model slots across crowns, not independent patients. NEVER refers only to retained labelled projected pairs. Unknown support remains all positive finite axial stiffnesses: MUST may have an unattained force infimum of zero. Force-share hulls consequently remain almost 0–100%; unmatched published profile coverage with ~98 pp mean width is not useful pressure accuracy.\n\nAn additional local external measurement was read as data: [Wiechens et al., Table 1](https://doi.org/10.1016/j.heliyon.2024.e28130) supplies one participant's repeated per-tooth observations. Of {r4['equal_count_pairs']} equal-count session pairs, {r4['equal_count_unequal_force_pairs']} have different reported force signals. FDI{collision['tooth']} has exactly {collision['count']} foil contacts in both observations, with T-Scan {collision['A']['force_pp']}% versus {collision['B']['force_pp']}% (difference {collision['force_difference_pp']} pp). Identity error is zero in the reported integer count. This rules out unique identification of the reported force from that count; measurement noise, sequential techniques, full contact geometry and causal explanations remain unresolved. The required extension is another force-sensitive observation, not a universal count-to-force formula.\n\nPublished norms are kept method- and tooth-specific. [Kordaß et al.](https://doi.org/10.1016/j.aanat.2023.152112) reports zero-contact fractions for particular posterior types; the lower-second-molar comparison is in rounds/R4.json and is descriptive only. [Ferrato Table 3](https://doi.org/10.11138/ads/2017.8.2.079) gives upper per-tooth relative force; its mean vector sums to 93% and is not renormalized. [Hattori Figure 1](https://doi.org/10.7144/sgf.2.111) gives the lower reference with ±1 pp digitization uncertainty inherited from X2. No published count is admitted as an individual generated-crown pass threshold (5/5 candidate sources rejected for that use). There is no uniquely supported fixed contact count per tooth type under our geometric observation operator.\n\nTwo constructed sufficiency probes also fail: exact equal area/count/centroid, identity error 0, gives 144 mm² different mask; exact equal sorted gaps and edge count, identity error 0, changes four tooth classes. These are mathematical counterexamples, not external physical validation. The minimum fixed-query extensions are reference-intersection area and labelled incidence respectively; full polygons and gap-pair sets are retained for further questions.\n\nControls: the inherited polygon operator agrees; exact TANDLAST class/force-hull outputs are recomputed and altered outputs rejected. The field-versus-LP R1 disagreement is {pair.get('constraint_optimizer vs field_generator')}/1728 (no superiority claim). A first-site four-participant grid check at 0.25→0.125 mm preserves its four decisions; other sites lack this check. Full wrong-output and source-integrity results are in raw/*CONTROLS.json. An unbounded-plane NaN bug and an exact-QP point outside its gap interval by at most 3.45e-14 mm were found, preserved in history/, and repaired without changing thresholds. The latter now tests an exact midpoint scenario.\n\nLimitations: supplied pose and predicted FDI are not clinically validated; projected signed gap is not physical 3D penetration; neighbour proximity is unsigned and has no distance-interpolation enclosure. The ±0.05 mm scenario is not a confidence interval. Contact set inclusion is rigorous for the real-arithmetic PL model; rigorous rounding/source-geometry enclosures are missing. R3 gap endpoints instead use outward lower bounds and exact rational upper witnesses on the rounded, nondegenerate projected triangles. No affine force sensitivity is reported. No calibrated stiffness, friction, rotations, preload or pressure law was added.\n\nFull replay cost: {cost.get('seconds'):.1f} s, peak child RSS {cost.get('peak_child_rss_MiB'):.1f} MiB, at most 4 threads, CPU only. Current lane data: {total_bytes / 1024 ** 2:.1f} MiB; cap 3 GiB. Upstream training, preparation, research and physical acquisition costs remain UNKNOWN. No 10× speed claim. One command: `./run_all.sh`; see README_DEMO.md, LEADERBOARD.csv, raw/TOOTH_LOAD_SETS.csv and figures/demo.png.\n"
    caution = f'Only **{snapshot_nonempty}/247** discriminating roof items have positive native contact area. Both discriminating complete-crown spatial sites have an empty native nominal band, and **0 complete-crown PASS results restore a positive native band**. The main fixed-pose gain therefore detects spurious contacts; it does not establish successful restoration of positive contact patterns.\n\n'
    txt = txt.replace('The changed operation retains', caution + 'The changed operation retains')
    if r5:
        extra = f"\nA fifth construction removes dependence on a single axial offset: integrate contact-mask disagreement over all common offsets. The interval identity gives `J=2∫min(|g_proposal−g_reference|,0.1mm)dA`, computed by triangle clipping. It is exactly invariant to a common axial shift in the represented real-arithmetic model. Against the separately frozen 0.2 mm³ criterion, **{r5['roof']['discriminating']}/1728** roof items discriminate, including **{r5['roof']['discriminating_nonempty_reference']}** with positive native nominal contact; **{r5['whole']['discriminating']}/18** whole-crown sites discriminate. All-method crown statuses: {r5['whole_all_methods']}. The integrated operator is mathematically a clipped absolute gap-error integral, not a new generator, measured force, or physiological closing trajectory. Earlier snapshot failures are preserved. Direct closure quadrature error is {r5['controls']['quadrature_error_mm3']:.3g} mm³; rigorous floating/source-geometry enclosure remains missing.\n"
        txt += extra
    (ROOT / 'RESULTS.md').write_text(txt)
    (ROOT / 'README_DEMO.md').write_text('# Contact-aware crown assessment\n\nRun `./run_all.sh` here. The demo freshly evaluates frozen generator outputs against local registered scan geometry, produces `results.json`, `LEADERBOARD.csv`, `raw/TOOTH_LOAD_SETS.csv` and [the figure](figures/demo.png). It does not retrain or rerun predecessor crown generation. It uses the two installed Python runtimes and explicitly pinned read-only predecessor data; a clean operating-system install is not tested.\n\nIdea: retain where each contact occurs before asking which tooth can carry load. Areas, counts and pass fractions can conceal a changed answer. A complete crown replaces its tooth in the full arch graph; all positive finite axial supports remain possible.\n\n' + txt[txt.index('| Question'):txt.index('The 18 sites')] + _release_expand('\n\nExternal referents: the original registered [Bits2Bites](https://ditto.ing.unimore.it/bits2bites/) and [Bite2Text](https://ditto.ing.unimore.it/bite2text/) surfaces anchor the geometric comparison. [Wiechens Table 1](https://doi.org/10.1016/j.heliyon.2024.e28130) supplies repeated contact-count and relative-force observations: the same reported count of 2 at tooth 11 accompanies 15.4% and 7.4% signals. Published tooth-type contact norms and force profiles are compared descriptively in EXTERNAL_REFERENTS.md and rounds/R4.json; these are unmatched observations, not individual clinical limits.\n\nWhat does not hold: no patient pressure or manufactured-crown force prediction is validated. Only 19/247 discriminating roof items have positive native nominal contact. Both discriminating complete-crown spatial sites have empty native contact, so their difference detects spurious contact. No complete-crown pass restores a positive native band. The fifth, pose-invariant contact-filtration query rejects every scored proposal under its separately frozen criterion. Published population profiles and methods are unmatched; force-share hulls remain almost 0–100%. All earlier failures remain visible.\n\nData licences: Bits2Bites CC BY-NC-SA (inherited dataset attribution; local registered STL inputs). Bite2Text exact data licence UNKNOWN in the local archive/author page; private local use only, no redistribution. Its predicted labels inherit the X11 model trained on Teeth3DS; no Teeth3DS mesh is exported here. Teeth3DS upstream snapshot licence binding is unresolved in X21, so no new redistribution claim. ToothFairy2 and mandible-defect datasets are unused. The local Wiechens article is CC BY per its XML licence. All scans use opaque source IDs; no patient records/images are used.\n\nDependencies: PROOF_LANE_GENCAD_V4 payload + quality.py, PROOF_LANE_GENCAD_V5 pure geometry helpers, PROOF_LANE_GENCAD_V5B R7 meshes, PROOF_LANE_FULL_CROWN R2/R3 meshes, X11 source labels, X21 continuous geometry kernels, TANDLAST model and engine snapshot. INPUT_LOCK_R1/R2/R3.json pins exact files; PREREG_R4 pins the local article. Source archives are read one case at a time, never extracted wholesale. Own arrays and Numba cache live under `@DENTAL_WORK_ROOT@/PROOF_LANE_GENCAD_V6`.\n\nTo test physically: follow LAB_PROTOCOL.md. FROZEN_MEASUREMENT_PREDICTIONS.json binds actual proposal mesh and field hashes before a future observation. No lab result is present.\n'))
    (ROOT / 'HANDOFF.md').write_text(f"# Next construction\n\nDelivered five frozen rounds: spatial roof decisions {r1['discriminating_L2']}/1728; complete-crown spatial decisions {r2['frontier_discriminating']}/18 sites; complete-crown tooth-load class differences {r3['frontier_discriminating']}/18; external equal-count/unequal-force observations {r4['equal_count_unequal_force_pairs']}/{r4['equal_count_pairs']}; analytical all-offset contact-filtration query rejects all scored proposals. Read RESULTS.md for denominators and bounds. Raw per-patch coordinates, complete per-tooth sets and same-information controls are retained. No upstream files were changed.\n\nCritical scope: only 19/247 discriminating roof tasks have positive native nominal contact; both complete-crown spatial differences detect spurious contacts on native-empty sites. No complete-crown PASS restores a positive native contact pattern. Do not present the headline 247 as evidence of successful functional crown design. R5 changes the observation to all offsets and returns 0 passing proposals; do not loosen its 0.2 mm³ criterion retrospectively.\n\nFailed/unknown: physical force and loaded contact unmeasured; gap scenario not scanner calibration; almost full-width force hulls; no universal per-type contact-count norm; 9/243 no-mesh requests; 2664/6912 roof rows unscored (1896 no prediction,768 no opposing support). Early polygon NaNs and invalid exact-QP point replay are preserved and fixed. First sufficiency attempt had 1.11e-16 centroid identity error and was rejected; the integer-coordinate pair has exact 0. Do not recycle failed claims as physical validation.\n\nNext operation: take the frozen two-crown local test pair in FROZEN_MEASUREMENT_PREDICTIONS.json, acquire calibrated spatial contact/force and loaded displacement in the same specimen/pose; replace the open support set with measured directional bounds, then rerun the unmodified contact and load consumers. The lab specification names required observations. If a measurement cannot be obtained, next computational construction is rigorous distance/pose enclosure at the TWO discriminating complete-crown sites, with unchanged thresholds and all-triangle pair completeness. Current one-site refinement is insufficient for a broad convergence claim.\n\nGraph: target DENT-VAL-BASELINE-COMPARISON exists in predecessor dispatches. Current packet and dispatch attempts returned STALE_INPUT for a changed draft-file set; feedback is attempted after the review seal; exact receipts under raw/GRAPH_*. No source or generated graph was rebuilt here. Coordinator must refresh the working-view registry and bind the pending review record; do not create a fake force-validation node.\n")
    return result['headline']
if __name__ == '__main__':
    print(run())
